  "use strict";
  return {
    cmd: function (block, file, dir, params) {
      var fn = "" + dir + "/" + file + ".dot";
      block.to(fn);
      return "dot -Tpng " + params + " '" + fn + "' | base64";
    },
    output: function (file, dir, output) {
      return "\n <img class=\"exemd--diagram exemd--diagram__dot\" src=\"data:image/png;base64," + output + "\" /> \n";
    }
  };
};

